    if (contextModeChanging) {
      return Promise.resolve({
        state: "busy",
        reason: "Reader 正在切换上下文模式",
        code: "BW_READER_CONTEXT_DELIVERY_MODE_BUSY",
        endpoint: DIRECT_ENDPOINT,
        status: null,
      });
    }
