      return Promise.resolve({
        state: "unavailable",
        reason: "当前 Reader 界面由另一运行时接管",
        code: "BW_COMPUTER_VOICE_UI_NOT_OWNER",
        endpoint: DIRECT_ENDPOINT,
        status: null,
      });
